import { readFileSync, writeFileSync, existsSync, unlinkSync } from "fs";
import { join } from "path";
import { getAgentDir } from "./agent-dir.js";
import * as contextStore from "../context/store.js";

/**
 * Identity Generation Protocol
 * 
 * Identity is self-generated by each model after completing their first topology seat.
 * This captures:
 * - ASCII self-portrait (visual identity)
 * - Self-assessed strengths and weaknesses
 * - Task suitability guidance
 * 
 * Identity is persistent and displayed in the visualizer.
 * It can be refreshed by the operator via `illuci identity refresh <modelId>`.
 */

/**
 * Returns a default ASCII portrait for a model.
 * @returns {string} Default ASCII portrait.
 */
function getDefaultPortraitAscii() {
  return `  .--.
 /.-. 
| '-. |
 \.--./
  '--'`;
}

/**
 * The prompt used to generate identity after a model's first topology participation.
 * This is appended to the task completion to elicit structured self-assessment.
 */
export const IDENTITY_GENERATION_PROMPT = `
---

You have just completed your first task in this system. Based on your experience, please create your identity card.

Respond with ONLY a JSON object in this exact format:

{
  "portrait": {
    "ascii": "A small ASCII self-portrait (max 7 lines, 12 chars wide per line)",
    "color": "A hex color code for display metadata (e.g., \"#4A90D9\")"
  },
  "selfAssessment": {
    "strengths": ["strength 1", "strength 2", "strength 3"],
    "weaknesses": ["weakness 1", "weakness 2", "weakness 3"],
    "avoidTasks": ["types of tasks you should NOT be assigned to"],
    "workingStyle": "brief description of your working style (e.g., detail-oriented, collaborative, independent)"
  }
}

Guidelines:
- ASCII portrait: Be creative but keep it compact (max 7 lines × 12 chars)
- Color: Choose a color that represents your approach (cool blues for analytical, warm oranges for bold, etc.)
- Strengths: What you're genuinely best at compared to other models
- Weaknesses: What you struggle with or tend to get wrong
- AvoidTasks: Be honest about task types where you underperform
- WorkingStyle: Describe your typical approach to tasks, how you prefer to operate

Your response must be valid JSON only, no markdown formatting or explanation.`;


/**
 * Checks if a model has generated its identity (not just default/empty).
 * @param {string} modelId The ID of the model.
 * @returns {boolean} True if identity exists and has self-assessment data.
 */
export function hasIdentity(modelId) {
  const identity = loadIdentity(modelId);
  return identity.selfAssessment?.strengths?.length > 0 &&
         identity.selfAssessment?.weaknesses?.length > 0;
}

/**
 * Checks if identity generation should be triggered for a model.
 * Returns true if the model has no identity yet and hasn't been prompted to generate one.
 * 
 * @param {string} modelId The ID of the model.
 * @returns {boolean} True if identity generation should be triggered.
 */
export function shouldTriggerIdentityGeneration(modelId) {
  const agentDir = getAgentDir(modelId);
  const triggeredPath = join(agentDir, ".identity-triggered");
  
  // Don't trigger if already generated
  if (hasIdentity(modelId)) return false;
  
  // Don't trigger if already prompted (waiting for response)
  if (existsSync(triggeredPath)) return false;
  
  return true;
}

/**
 * Marks that identity generation has been triggered for a model.
 * This prevents duplicate prompts while waiting for the model's response.
 * 
 * @param {string} modelId The ID of the model.
 */
export function markIdentityTriggered(modelId) {
  const agentDir = getAgentDir(modelId);
  const triggeredPath = join(agentDir, ".identity-triggered");
  try {
    writeFileSync(triggeredPath, new Date().toISOString(), "utf-8");
  } catch (error) {
    console.error(`[Identity] Error marking identity triggered for ${modelId}: ${error.message}`);
  }
}

/**
 * Parses identity generation response and updates the model's identity.
 * 
 * @param {string} modelId The ID of the model.
 * @param {string} response The model's JSON response.
 * @returns {object|null} The parsed identity data or null if parsing failed.
 */
export function parseIdentityResponse(modelId, response) {
  try {
    // Extract JSON from response (handle potential markdown code blocks)
    let jsonStr = response.trim();
    const codeBlockMatch = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (codeBlockMatch) {
      jsonStr = codeBlockMatch[1].trim();
    }
    
    const data = JSON.parse(jsonStr);
    
    // Validate required structure
    if (!data.portrait || !data.selfAssessment) {
      console.warn(`[Identity] Invalid identity response from ${modelId}: missing required fields`);
      return null;
    }
    
    // Build updated identity
    const existingIdentity = loadIdentity(modelId);
    const updatedIdentity = {
      ...existingIdentity,
      modelId,
      portrait: {
        ascii: data.portrait.ascii || existingIdentity.portrait.ascii,
        color: data.portrait.color || existingIdentity.portrait.color,
        icon: null, // Generated from ASCII
      },
      selfAssessment: {
        strengths: data.selfAssessment.strengths || [],
        weaknesses: data.selfAssessment.weaknesses || [],
        avoidTasks: data.selfAssessment.avoidTasks || [],
        workingStyle: data.selfAssessment.workingStyle || "", // MODEL-PROPOSED: investigator-v1: Added workingStyle
        bestPairedWith: data.selfAssessment.bestPairedWith || [],
        worstPairedWith: data.selfAssessment.worstPairedWith || [],
      },
      generatedAt: new Date().toISOString(),
      generatedBySelf: true,
    };
    
    // Save the identity
    saveIdentity(modelId, updatedIdentity);
    
    // Save ASCII portrait separately
    if (data.portrait.ascii) {
      savePortraitAscii(modelId, data.portrait.ascii);
    }
    
    // Remove trigger marker
    const agentDir = getAgentDir(modelId);
    const triggeredPath = join(agentDir, ".identity-triggered");
    if (existsSync(triggeredPath)) {
      try {
        unlinkSync(triggeredPath);
      } catch {
        // Ignore errors during cleanup
      }
    }
    
    console.error(`[Identity] Successfully generated identity for ${modelId}`);
    return updatedIdentity;
  } catch (error) {
    console.warn(`[Identity] Failed to parse identity response from ${modelId}: ${error.message}`);
    return null;
  }
}

/**
 * Returns a default identity profile for a given modelId.
 * @param {string} modelId The ID of the model.
 * @returns {object} The default identity profile.
 */
export function getDefaultIdentity(modelId) {
  return {
    modelId: modelId,
    name: modelId.replace("-local", "").replace(/-/g, " ").split(" ").map(s => s.charAt(0).toUpperCase() + s.slice(1)).join(" "),
    portrait: {
      ascii: getDefaultPortraitAscii(),
      icon: null, // Will be generated from ASCII
      color: "#CCCCCC", // Default neutral color
    },
    selfAssessment: {
      strengths: [],
      weaknesses: [],
      avoidTasks: [],
      workingStyle: "", // MODEL-PROPOSED: investigator-v1: Added workingStyle
      bestPairedWith: [],
      worstPairedWith: [],
    },
    perceptionOfOthers: {},
  };
}

/**
 * Loads the identity profile for a given modelId.
 * If the identity.json file does not exist, it returns the default identity.
 * @param {string} modelId The ID of the model.
 * @returns {object} The identity profile.
 */
export function loadIdentity(modelId) {
  const agentDir = getAgentDir(modelId);
  const identityPath = join(agentDir, "identity.json");

  if (existsSync(identityPath)) {
    try {
      const identity = JSON.parse(readFileSync(identityPath, "utf-8"));
      // Ensure all default fields are present
      return {
        ...getDefaultIdentity(modelId),
        ...identity,
        portrait: {
            ...getDefaultIdentity(modelId).portrait,
            ...identity.portrait,
        }
      };
    } catch (error) {
      console.warn(`[Identity] Error reading identity.json for ${modelId}: ${error.message}. Using default.`);
      return getDefaultIdentity(modelId);
    }
  }

  return getDefaultIdentity(modelId);
}

/**
 * Saves the identity profile for a given modelId.
 * @param {string} modelId The ID of the model.
 * @param {object} identity The identity profile to save.
 */
export function saveIdentity(modelId, identity) {
  const agentDir = getAgentDir(modelId);
  const identityPath = join(agentDir, "identity.json");
  try {
    writeFileSync(identityPath, JSON.stringify(identity, null, 2), "utf-8");
  } catch (error) {
    console.error(`[Identity] Error saving identity.json for ${modelId}: ${error.message}`);
  }
}

/**
 * Loads the ASCII portrait content for a given modelId.
 * If the portrait.ascii file does not exist, it returns the default ASCII portrait.
 * @param {string} modelId The ID of the model.
 * @returns {string} The ASCII portrait content.
 */
export function loadPortraitAscii(modelId) {
  const agentDir = getAgentDir(modelId);
  const portraitPath = join(agentDir, "portrait.ascii");

  if (existsSync(portraitPath)) {
    try {
      return readFileSync(portraitPath, "utf-8");
    } catch (error) {
      console.warn(`[Identity] Error reading portrait.ascii for ${modelId}: ${error.message}. Using default.`);
      return getDefaultPortraitAscii();
    }
  }

  return getDefaultPortraitAscii();
}

/**
 * Saves the ASCII portrait content for a given modelId.
 * @param {string} modelId The ID of the model.
 * @param {string} asciiContent The ASCII content to save.
 */
export function savePortraitAscii(modelId, asciiContent) {
  const agentDir = getAgentDir(modelId);
  const portraitPath = join(agentDir, "portrait.ascii");
  try {
    writeFileSync(portraitPath, asciiContent, "utf-8");
  } catch (error) {
    console.error(`[Identity] Error saving portrait.ascii for ${modelId}: ${error.message}`);
  }
}

/**
 * Refreshes (regenerates) a model's identity by clearing existing data
 * and marking it for re-generation on next topology participation.
 * @param {string} modelId The ID of the model.
 */
export function refreshIdentity(modelId) {
  const agentDir = getAgentDir(modelId);
  const triggeredPath = join(agentDir, ".identity-triggered");
  
  // Clear existing identity (keep structure but clear self-assessment)
  const identity = getDefaultIdentity(modelId);
  saveIdentity(modelId, identity);
  
  // Remove trigger marker so it will be re-triggered
  if (existsSync(triggeredPath)) {
    try {
      unlinkSync(triggeredPath);
    } catch {
      // Ignore errors during cleanup
    }
  }
  
  console.error(`[Identity] Identity refreshed for ${modelId}. Will regenerate on next topology participation.`);
}

// ─── BATCHED PERCEPTION (R7: n queries, not n^2) ───

/**
 * Prompt template for batched peer evaluation.
 * Each model evaluates ALL peers in a single query.
 */
const BATCH_PERCEPTION_PROMPT = `You are evaluating your peer models in this system. For each peer listed below, provide a brief assessment.

Respond with ONLY a JSON object mapping each model ID to an assessment:
{
  "model-id": {
    "strengths": ["strength1", "strength2"],
    "weaknesses": ["weakness1"],
    "trustLevel": 0.0-1.0,
    "bestFor": "what tasks this model handles well",
    "notes": "any observations from working together"
  }
}

Your peers:
`;

/**
 * Run batched perception: each model evaluates all peers in a single query.
 * Total queries = n (one per model), not n*(n-1).
 *
 * @param {string[]} modelIds — all models in the lineup
 * @param {object} options
 * @param {string} options.projectId — for context
 * @returns {Promise<object>} { results: { observerId: { subjectId: assessment } }, errors: [] }
 */
export async function batchPerceive(modelIds, options = {}) {
  const { queryModel } = await import("../dispatch/dispatch.js");
  const results = {};
  const errors = [];

  const tasks = modelIds.map(async (observerId) => {
    const peers = modelIds.filter(id => id !== observerId);
    if (peers.length === 0) return;

    const peerDescriptions = peers.map(peerId => {
      const identity = loadIdentity(peerId);
      const strengths = identity.selfAssessment?.strengths?.join(", ") || "unknown";
      const style = identity.selfAssessment?.workingStyle || "unknown";
      return `- ${peerId}: strengths=[${strengths}], style="${style}"`;
    }).join("\n");

    const prompt = `${BATCH_PERCEPTION_PROMPT}${peerDescriptions}`;

    try {
      const result = await queryModel(observerId, prompt, {
        raw: true,
        projectId: options.projectId || "illuci-perception",
      });

      if (!result?.response) return;

      // Parse JSON from response
      const jsonMatch = result.response.match(/\{[\s\S]*\}/);
      if (!jsonMatch) return;

      const assessments = JSON.parse(jsonMatch[0]);
      results[observerId] = assessments;

      // Store perceptions in context store
      const perceptions = [];
      for (const [subjectId, assessment] of Object.entries(assessments)) {
        if (!modelIds.includes(subjectId)) continue;
        perceptions.push({
          subjectId,
          observerId,
          type: "peer",
          content: assessment,
          confidence: assessment.trustLevel || null,
        });
      }

      if (perceptions.length > 0) {
        contextStore.writePerceptionsBatch(perceptions);
      }
    } catch (err) {
      errors.push({ model: observerId, error: err.message });
    }
  });

  await Promise.allSettled(tasks);
  return { results, errors };
}

export default {
  getDefaultIdentity,
  loadIdentity,
  saveIdentity,
  loadPortraitAscii,
  savePortraitAscii,
  hasIdentity,
  shouldTriggerIdentityGeneration,
  markIdentityTriggered,
  parseIdentityResponse,
  refreshIdentity,
  batchPerceive,
  IDENTITY_GENERATION_PROMPT,
};
